--{{{
-- ## Antigravity Dashboard — Core
--
-- Loads `$JSON_PATH/antigravity.json` (generated by `sh/fetch_antigravity.sh`) into a
-- global `ANTIGRAVITY` table. Reads are cached in memory and re-populated when
-- `antigravity.json`'s mtime changes (checked at most once every 3 seconds).
--
-- **Exposed functions:**
-- - `load_antigravity_data()` — returns cached Antigravity data table
-- - `ANTIGRAVITY.populate()` — reads and parses `antigravity.json`
-- - `antigravity_refresh_action()` — runs `sh/fetch_antigravity.sh &` in the background
--}}}

local agy_cache_storage = nil
local agy_cache_mtime = 0
local last_agy_mtime_check = 0

local function agy_resolve_file(fname)
	local base_dir = (JSON_PATH and JSON_PATH ~= "") and JSON_PATH or ((os.getenv("HOME") or "/tmp") .. "/.conky/tmp/")
	local primary = base_dir .. fname
	local attrs = lfs and lfs.attributes(primary)
	local m = attrs and attrs.modification or 0

	local user_path = (os.getenv("HOME") or "/tmp") .. "/.conky/tmp/" .. fname
	if user_path ~= primary and lfs then
		local uattrs = lfs.attributes(user_path)
		local um = uattrs and uattrs.modification or 0
		if um > m then
			return user_path, um
		end
	end
	return primary, m
end

local function agy_json_changed()
	local _, m = agy_resolve_file("antigravity.json")
	if agy_cache_mtime ~= m then
		agy_cache_mtime = m
		return true
	end
	return false
end

ANTIGRAVITY = ANTIGRAVITY or {}

function ANTIGRAVITY.populate()
	local path, m = agy_resolve_file("antigravity.json")
	agy_cache_mtime = m
	local f = io.open(path, "r")
	if not f then
		agy_cache_storage = {}
		return
	end
	local c = f:read("*all")
	f:close()
	if not c or c == "" or not json then
		agy_cache_storage = {}
		return
	end
	local decoded = json.decode(c)
	agy_cache_storage = (type(decoded) == "table") and decoded or {}
end

function load_antigravity_data()
	local now = os.time()
	if not agy_cache_storage or (now - last_agy_mtime_check >= 3) then
		last_agy_mtime_check = now
		if agy_json_changed() or not agy_cache_storage then
			ANTIGRAVITY.populate()
		end
	end
	return agy_cache_storage or {}
end

local function get_agy_script_path()
	local root = (script_dir and script_dir ~= "") and script_dir or ((os.getenv("HOME") or "/home/molnar") .. "/.conky/")
	if not root:match("/$") then
		root = root .. "/"
	end
	return root .. "sh/fetch_antigravity.sh"
end

function antigravity_refresh_action()
	local sh = get_agy_script_path()
	if sh and sh ~= "" and lfs and lfs.attributes(sh) then
		os.execute("bash " .. sh .. " >/dev/null 2>&1 &")
	end
end

load_antigravity_data()
